//! Ring perception parity with RDKit: `RingInfo::atom_rings` / `bond_rings`
//! must equal RDKit's `GetRingInfo().AtomRings()` / `BondRings()` element for
//! element (same rings, same ring order, same start atom and direction).
//! For aromatic molecules also the canonical atom ranks and the canonical
//! Kekulé structure (what RDKit's MMFF typer kekulizes to) are compared.
//! Fixtures: `tests/data/rings/rings.json`, generated by
//! `tools/gen_ring_reference.py`.

use molecule_optimizer_rs::Molecule;
use molecule_optimizer_rs::core::BondOrder;
use molecule_optimizer_rs::io::molfile::read_sdf_lenient;
use molecule_optimizer_rs::perception::{canonical_atom_ranks, kekulized_copy_canonical};
use std::path::PathBuf;

fn root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

fn as_rings(v: &serde_json::Value) -> Vec<Vec<usize>> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|r| r.as_array().unwrap().iter().map(|x| x.as_u64().unwrap() as usize).collect())
        .collect()
}

fn as_list(v: &serde_json::Value) -> Vec<usize> {
    v.as_array().unwrap().iter().map(|x| x.as_u64().unwrap() as usize).collect()
}

/// (file, record, molecule) for every non-failed fixture record.
fn records() -> Vec<(String, serde_json::Value, Molecule)> {
    let text = std::fs::read_to_string(root().join("tests/data/rings/rings.json")).unwrap();
    let data: serde_json::Value = serde_json::from_str(&text).unwrap();
    let mut out = Vec::new();
    for (file, recs) in data.as_object().unwrap() {
        let sdf = std::fs::read_to_string(root().join(file)).unwrap();
        let mols = read_sdf_lenient(&sdf);
        for rec in recs.as_array().unwrap() {
            if rec.get("failed").is_some() {
                continue;
            }
            let idx = rec["index"].as_u64().unwrap() as usize;
            let mol = mols[idx].as_ref().unwrap_or_else(|e| panic!("{file}[{idx}]: read failed: {e}")).clone();
            out.push((format!("{file}[{idx}] {}", rec["name"].as_str().unwrap_or("")), rec.clone(), mol));
        }
    }
    out
}

#[test]
fn rings_match_rdkit() {
    let mut n_rings = 0;
    let mut failures = Vec::new();
    let recs = records();
    for (label, rec, mut mol) in recs.clone() {
        let ri = mol.rings();
        let atom_rings = as_rings(&rec["atom_rings"]);
        let bond_rings = as_rings(&rec["bond_rings"]);
        n_rings += atom_rings.len();
        if ri.atom_rings != atom_rings || ri.bond_rings != bond_rings {
            failures.push(format!("{label}:\n    ours  {:?}\n    rdkit {:?}", ri.atom_rings, atom_rings));
        }
    }
    println!("{} molecules, {n_rings} rings compared; {} mismatches", recs.len(), failures.len());
    for f in &failures {
        println!("  {f}");
    }
    assert!(failures.is_empty(), "{} molecules differ from RDKit ring perception", failures.len());
}

#[test]
fn canonical_ranks_and_kekule_match_rdkit() {
    let mut n = 0;
    let mut rank_failures = Vec::new();
    let mut kek_failures = Vec::new();
    for (label, rec, mol) in records() {
        let Some(ranks) = rec.get("ranks") else { continue };
        n += 1;
        let theirs = as_list(ranks);
        let ours = canonical_atom_ranks(&mol);
        if ours != theirs {
            rank_failures.push(format!("{label}:\n    ours  {ours:?}\n    rdkit {theirs:?}"));
        }
        if rec["kekule_double"].is_null() {
            continue;
        }
        let theirs = as_list(&rec["kekule_double"]);
        let k = kekulized_copy_canonical(&mol).unwrap();
        let ours: Vec<usize> = (0..k.num_bonds()).filter(|&b| k.bond(b).order == BondOrder::Double).collect();
        if ours != theirs {
            kek_failures.push(format!("{label}:\n    ours  {ours:?}\n    rdkit {theirs:?}"));
        }
    }
    println!(
        "{n} aromatic molecules: {} canonical-rank mismatches, {} Kekule mismatches",
        rank_failures.len(),
        kek_failures.len()
    );
    for f in rank_failures.iter().chain(&kek_failures) {
        println!("  {f}");
    }
    assert!(kek_failures.is_empty(), "{} Kekule structures differ from RDKit", kek_failures.len());
    assert!(rank_failures.is_empty(), "{} canonical rankings differ from RDKit", rank_failures.len());
}
